<?php
require_once __DIR__.'/../app/bootstrap.php';require_admin();$id=(int)($_GET['id']??$_POST['id']??0);
$q=db()->prepare('SELECT u.*,p.* FROM users u LEFT JOIN profiles p ON p.user_id=u.id WHERE u.id=?');$q->execute([$id]);$target=$q->fetch();if(!$target){http_response_code(404);exit('Usuario no encontrado.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$username=trim((string)$_POST['username']);$email=trim((string)$_POST['email']);$display=trim((string)$_POST['display_name']);
 $role=in_array($_POST['role']??'', ['admin','user'],true)?$_POST['role']:'user';$status=in_array($_POST['status']??'', ['pending','active','blocked'],true)?$_POST['status']:'pending';
 if(!preg_match('/^[A-Za-z0-9_.-]{3,40}$/',$username))throw new RuntimeException('Nombre de usuario inválido.');if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Correo inválido.');
 if($id===(int)user()['id']&&($role!=='admin'||$status!=='active'))throw new RuntimeException('No puedes quitarte el rol administrador ni bloquear tu propia sesión.');
 $dup=db()->prepare('SELECT COUNT(*) FROM users WHERE (username=? OR email=?) AND id<>?');$dup->execute([$username,$email,$id]);if((int)$dup->fetchColumn())throw new RuntimeException('El usuario o correo ya está ocupado.');
 db()->beginTransaction();try{
  db()->prepare('UPDATE users SET username=?,email=?,role=?,status=?,updated_at=NOW() WHERE id=?')->execute([$username,$email,$role,$status,$id]);
  db()->prepare('INSERT INTO profiles(user_id,display_name,bio,location,business_local,business_number,business_address,phone,whatsapp,google_maps_url,show_usd) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE display_name=VALUES(display_name),bio=VALUES(bio),location=VALUES(location),business_local=VALUES(business_local),business_number=VALUES(business_number),business_address=VALUES(business_address),phone=VALUES(phone),whatsapp=VALUES(whatsapp),google_maps_url=VALUES(google_maps_url),show_usd=VALUES(show_usd)')->execute([$id,$display?:$username,trim((string)$_POST['bio']),trim((string)$_POST['location']),trim((string)$_POST['business_local']),trim((string)$_POST['business_number']),trim((string)$_POST['business_address']),trim((string)$_POST['phone']),preg_replace('/\D+/','',(string)$_POST['whatsapp']),trim((string)$_POST['google_maps_url']),isset($_POST['show_usd'])?1:0]);
  $pass=(string)($_POST['new_password']??'');if($pass!==''){if(strlen($pass)<10)throw new RuntimeException('La contraseña debe tener al menos 10 caracteres.');db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($pass,PASSWORD_DEFAULT),$id]);}
  db()->commit();flash('success','Usuario actualizado correctamente.');redirect('../admin/user_edit.php?id='.$id);
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
$counts=user_content_counts($id);$adminPage='users';$adminTitle='Editar usuario';$adminSubtitle='Cuenta, perfil comercial, seguridad y estado';require __DIR__.'/partials/header.php';
?>
<div class="admin-grid-2"><section class="admin-card"><div class="panel-head"><div><h2>👤 Cuenta</h2><p>ID #<?=$id?> · <?=array_sum($counts)?> registros relacionados</p></div><a class="admin-btn small" href="users.php">← Volver</a></div>
<form method="post" class="admin-form-stack"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><div class="form-grid"><label>Usuario<input name="username" required value="<?=e($target['username'])?>"></label><label>Correo<input type="email" name="email" required value="<?=e($target['email'])?>"></label><label>Rol<select name="role"><option value="user">Vendedor</option><option value="admin" <?=$target['role']==='admin'?'selected':''?>>Administrador</option></select></label><label>Estado<select name="status"><?php foreach(['pending'=>'Pendiente','active'=>'Activo','blocked'=>'Bloqueado'] as $v=>$l):?><option value="<?=$v?>" <?=$target['status']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label></div><label>Nueva contraseña <small>(dejar vacío para conservarla)</small><input type="password" name="new_password" minlength="10" autocomplete="new-password"></label>
<h3>🏪 Perfil comercial</h3><div class="form-grid"><label>Nombre visible<input name="display_name" value="<?=e($target['display_name']??'')?>"></label><label>Ciudad / comuna<input name="location" value="<?=e($target['location']??'')?>"></label><label>Nombre del local<input name="business_local" value="<?=e($target['business_local']??'')?>"></label><label>Número del local<input name="business_number" value="<?=e($target['business_number']??'')?>"></label><label>Teléfono<input name="phone" value="<?=e($target['phone']??'')?>"></label><label>WhatsApp<input name="whatsapp" value="<?=e($target['whatsapp']??'')?>"></label></div><label>Dirección<input name="business_address" value="<?=e($target['business_address']??'')?>"></label><label>Google Maps<input type="url" name="google_maps_url" value="<?=e($target['google_maps_url']??'')?>"></label><label>Descripción<textarea name="bio" rows="5"><?=e($target['bio']??'')?></textarea></label><label class="check-card"><input type="checkbox" name="show_usd" <?=$target['show_usd']?'checked':''?>> Mostrar conversión CLP/USD</label><button class="admin-btn primary">💾 Guardar cambios</button></form></section>
<aside><section class="admin-card"><h2>📊 Datos relacionados</h2><?php foreach($counts as $k=>$v):?><div class="metric-row"><span><?=e(ucfirst($k))?></span><b><?=$v?></b></div><?php endforeach;?></section><section class="admin-card danger-zone"><h2>⚠️ Zona delicada</h2><p>Para borrar artículos, feedback o la cuenta completa utiliza la pantalla de eliminación verificada.</p><?php if($id!==(int)user()['id']):?><a class="admin-btn danger wide" href="user_delete.php?id=<?=$id?>">Vaciar o eliminar cuenta</a><?php endif;?></section></aside></div>
